class Configuration {
private:
    // Managed by static function
    static int globalSetting;
    int instanceData; // Non-static

public:
    // Definition: Cannot access 'this' or instanceData
    static void setGlobal(int val) {
        globalSetting = val;
    }

    static int getGlobal() {
        return globalSetting;
    }
};

// Definition of static data member
int Configuration::globalSetting = 100;

// Usage: Called without an instance
Configuration::setGlobal(50);
int current = Configuration::getGlobal();

// current == 50
